import{_ as t,o as r,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-05-31","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-05-31","date":"2022-05-31T00:00:00.000Z","updated":"2022-06-01T00:00:00.000Z","tags":["Ceph","分布式存储","自动化","磁盘管理","监控"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-05-31.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-05-31.md","lastUpdated":1780459816000}'),a={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-05-31.md"};function p(n,e,i,_,c,l){return r(),o("div",null,[...e[0]||(e[0]=[s("<p>会议纪要：</p><ol><li><p><strong>磁盘扫描改进</strong>：Paul致力于改进磁盘扫描功能，特别是针对外部存储设备。他正在尝试通过使用<code>gather facts</code>工具来提高扫描效率。目前尚未决定是否采用此方法，但初步反馈是积极的，计划进行概念验证。</p></li><li><p><strong>磁盘库存同步问题</strong>：讨论了如何保持主机与Ceph集群信息同步的问题。提出使用<code>gather facts</code>工具收集磁盘信息，并确保与当前库存数据同步。强调了代码同步的重要性，以避免信息不一致。</p></li><li><p><strong>Prometheus服务发现</strong>：提出了一个PR，准备用于代码审查。该变更涉及代码移动和重构，以简化审查过程。讨论了服务发现端点的使用，以及如何确保Prometheus实例能够像外部工具一样利用这一新功能。</p></li><li><p><strong>证书管理</strong>：讨论了处理外部监控工具部署时所需的证书问题。建议提供一种命令生成证书，以便用户手动设置在其Prometheus实例上。还考虑了在Ceph中设置一个使用安全证书的Cherry Pie服务器的可能性。</p></li><li><p><strong>NFS和Ganesha配置</strong>：讨论了OpenStack环境中NFS服务的部署，特别是关于Ganesha配置和虚拟IP管理的PoC。目标是不使用HA代理，而是依赖Keeper FD来管理活动Ganesha服务器的浮动IP。</p></li><li><p><strong>功能跟踪和API设计</strong>：确认了创建一个功能跟踪票据，记录Francesco的想法和PoC细节，以便Sephirium核心团队可以开始工作。讨论了如何设计API以减少用户混淆，特别是在部署时是否使用HA代理的情况下。</p></li><li><p><strong>后续行动</strong>：约定在下次会议前更新PoC的进展，并在特征跟踪器票据中添加更多细节。确认了继续推进这些项目的计划，并在下次会议中回顾进度。</p></li></ol>",2)])])}const d=t(a,[["render",p]]);export{g as __pageData,d as default};
